repo.invoices.py:
"""Invoice records."""


class Invoice:
    def __init__(self, client, due):
        self.client = client
        self.due = due

    def __repr__(self):
        return "Invoice(%r, %r)" % (self.client, self.due)


ROWS = [('hale', 43), ('ivory', 34), ('ivory', 56), ('ivory', 22), ('ivory', 8), ('hale', 7), ('hale', 45)]


def load_invoices():
    """Yield the stored invoices one at a time."""
    for client, due in ROWS:
        yield Invoice(client, due)

repo.cumulative.py:
"""Running totals over invoices."""


def running_due(invoices):
    """Return the running total of due after each invoice, in order."""
    out = []
    total = 0
    for i in range(len(invoices) - 1):
        total += invoices[i].due
        out.append(total)
    return out


def final_due(invoices):
    """Return the total due of all invoices, or 0 when there are none."""
    totals = running_due(invoices)
    return totals[-1] if totals else 0


def describe_invoice(invoice):
    """Return a one-line description of a invoice."""
    return "%s: %s" % (invoice.client, invoice.due)


def largest_due(invoices):
    """Return the largest due, or None when there are no invoices."""
    values = [x.due for x in invoices]
    return max(values) if values else None

